var fib = function(n) {
    // Base cases
    if (n <= 1) {
        return n;
    }

    // Iteratively compute Fibonacci using only two variables
    let previous = 0; // F(0)
    let current = 1;  // F(1)

    for (let i = 2; i <= n; i++) {
        const next = previous + current;
        previous = current;
        current = next;
    }

    return current;
};
